from collections import Counter, deque, defaultdict

def components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen, out = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            out.append((color, cells))
    return out

def shape_key(cells):
    variants = []
    for reflect in (1, -1):
        for k in range(4):
            pts = []
            for r, c in cells:
                x, y = r, reflect*c
                for _ in range(k):
                    x, y = y, -x
                pts.append((x, y))
            a, b = min(x for x,y in pts), min(y for x,y in pts)
            variants.append(tuple(sorted((x-a, y-b) for x,y in pts)))
    return min(variants)

def is_l(cells):
    s = set(cells)
    if len(s) < 4:
        return False
    rs = [r for r,c in s]; cs = [c for r,c in s]
    r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
    patterns = [
        {(r,c0) for r in range(r0,r1+1)} | {(r0,c) for c in range(c0,c1+1)},
        {(r,c0) for r in range(r0,r1+1)} | {(r1,c) for c in range(c0,c1+1)},
        {(r,c1) for r in range(r0,r1+1)} | {(r0,c) for c in range(c0,c1+1)},
        {(r,c1) for r in range(r0,r1+1)} | {(r1,c) for c in range(c0,c1+1)},
    ]
    return any(s == p for p in patterns)

def transform(grid):
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    objs = components(grid, bg)
    # Use the largest one-cell-thick L as the color key.
    markers = [(len(cells), color, cells) for color,cells in objs if is_l(cells)]
    if not markers:
        return out
    _, marker_color, marker = max(markers, key=lambda x: x[0])
    mkey = shape_key(marker)
    mr = sum(r for r,c in marker)/len(marker)
    mc = sum(c for r,c in marker)/len(marker)
    groups = defaultdict(list)
    for color,cells in objs:
        if cells is marker or shape_key(cells) == mkey:
            continue
        groups[shape_key(cells)].append((color,cells))
    repeated = [items for items in groups.values() if len(items) >= 2]
    if not repeated:
        return out
    # The repeated motif with the greatest area is the target pair.
    # Recolor the copy farther from the L-shaped key.
    items = max(repeated, key=lambda group: len(shape_key(group[0][1])))
    color,cells = max(items, key=lambda item: abs(sum(r for r,c in item[1])/len(item[1])-mr)+abs(sum(c for r,c in item[1])/len(item[1])-mc))
    for r,c in cells:
        out[r][c] = marker_color
    return out
